[FunctionName("IndexDocumentOrchestrator")]
public async Task IndexDocumentAsync(
    [OrchestrationTrigger] TaskOrchestrationContext context,
    string documentId)
{
    try
    {
        // Step 1: Fetch and chunk document
        var chunks = await context.CallActivityAsync<List<DocumentChunk>>(
            "ChunkDocument", documentId);

        // Step 2: Generate embeddings (parallel, with retry)
        var embeddingTasks = chunks.Select(chunk =>
            context.CallActivityWithRetryAsync<float[]>("GenerateEmbedding",
                new RetryOptions(TimeSpan.FromSeconds(5), 3), chunk.Text));
        var embeddings = await Task.WhenAll(embeddingTasks);

        // Step 3: Store in vector database
        await context.CallActivityAsync("StoreVectors", new VectorBatch
        {
            DocumentId = documentId,
            Chunks = chunks,
            Embeddings = embeddings
        });

        // Step 4: Trigger search index update
        await context.CallActivityAsync("UpdateSearchIndex", documentId);
    }
    catch (Exception ex)
    {
        // Dead-letter for persistent failures
        await context.CallActivityAsync("NotifyIndexingFailure",
            new FailureNotification { DocumentId = documentId, Error = ex.Message });
    }
}

// Idempotent embedding generation with caching
[FunctionName("GenerateEmbedding")]
public async Task<float[]> GenerateEmbedding(
    [ActivityTrigger] string text, ILogger log)
{
    var cacheKey = $"emb:{Sha256(text)}";
    var cached = await _cache.GetAsync<float[]>(cacheKey);
    if (cached != null) return cached;

    var response = await _embeddingClient.GenerateAsync(text);
    await _cache.SetAsync(cacheKey, response.ToArray(), TimeSpan.FromDays(7));
    return response.ToArray();
}
